mapper.select:
select id, user_id, content, content_hash, category, source_type, image_url, status,
       verdict, verdict_source, confidence, reasoning_chain, ai_summary, version,
       hit_count, assignee_id, deadline, authority_id, create_time, update_time, complete_time
from t_fact_check_record

    and category = #{category}
    and status = #{status}
    and verdict = #{verdict}
    and content like concat('%', #{keyword}, '%')

order by create_time desc

select id, user_id, content, content_hash, category, source_type, image_url, status,
       verdict, verdict_source, confidence, reasoning_chain, ai_summary, version,
       hit_count, assignee_id, deadline, authority_id, create_time, update_time, complete_time
